insert into public.question_attempts
    (id, user_id, question_id, is_correct, given_answer, time_taken_seconds, source, attempted_at, reasoning, reasoning_verdict)
values
    ('33b960f0-a882-44bb-838f-c55ebf634131', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'b28ac269-650b-4292-8975-4380c3952d5a', false, '{"selectedOptions":[0]}', 64, 'assessment', now() - interval '821532 seconds', 'Two 10 Ω resistors in parallel make 20 Ω.', 'flawed'),
    ('e44877af-7eea-4461-84a2-3f3695cf6302', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '43770002-8762-4881-8ec9-d41ad7e134dd', true, '{"selectedOptions":[2]}', 25, 'assessment', now() - interval '821457 seconds', null, 'missing'),
    ('e1c7ad44-7b2a-47ff-8a53-b8a3f9765251', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'dd5c1682-0093-477a-8bd8-ed8cafd851a7', true, '{"selectedOptions":[0]}', 75, 'assessment', now() - interval '821382 seconds', 'because paper gives diffuse reflection: its tiny surface bumps face many directions, so reflected rays scatter, though each one obeys the laws of reflection', 'sound'),
    ('7926915a-49cb-47ca-8938-7d21959a1f65', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '592dced7-4d6b-436b-8d7c-f2843b2a7f39', false, '{"selectedOptions":[3]}', 70, 'assessment', now() - interval '821307 seconds', 'not sure', 'missing'),
    ('93bbd0c1-e85c-4223-8dee-8ffa61a5d128', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'abd1710a-33da-4b35-8f05-d7fcc60027e7', true, '{"selectedOptions":[1]}', 93, 'assessment', now() - interval '821232 seconds', 'because the minus sign means the image is real and inverted; the size |m| = 2 means it is twice as large as the object', 'sound'),
    ('d13b113a-c0ca-44ce-8a0d-8127faef17f6', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '1f363bb6-9fdc-4436-83c4-ca9c632688f7', true, '{"selectedOptions":[1]}', 116, 'assessment', now() - interval '821157 seconds', 'because in series the same current flows through every component, so identical bulbs glow equally', 'sound'),
    ('2e32f8c4-9a70-4284-89dc-88f468e79a74', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '57f4bac0-8d13-498d-8567-afbab828b3f4', true, '{"selectedOptions":[2]}', 107, 'assessment', now() - interval '821082 seconds', 'because by Ohm''s law I = V/R; R is fixed for the conductor, so doubling V doubles I', 'sound'),
    ('caa5fe36-cf48-4292-8644-2e8472a9a203', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '0e26472d-1d73-4655-8d35-0755bcfe4c73', false, '{"selectedOptions":[1]}', 92, 'assessment', now() - interval '821007 seconds', null, 'missing'),
    ('b95f0ff0-a4ca-44c3-8b81-b5d40f05a8fb', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'fac59f2d-cfcd-43b8-8063-553e8b9373ca', false, '{"selectedOptions":[0]}', 96, 'assessment', now() - interval '820932 seconds', null, 'missing'),
    ('be6a9b60-f8d2-437a-8ad3-bf8c53d6a170', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'de06817c-4d9f-400d-8dec-1467419f33db', false, '{"selectedOptions":[1]}', 67, 'assessment', now() - interval '820857 seconds', 'A fuse must not melt easily, so it needs a high melting point.', 'flawed'),
    ('7ad7d757-e2ab-4bd5-8099-f8a0de268100', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '6ca49128-eaea-41b4-8324-b19fdbcaca07', true, '{"selectedOptions":[1]}', 113, 'assessment', now() - interval '820782 seconds', null, 'missing'),
    ('432b2722-075e-42b3-8e3d-e091c8cc06e6', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '109cb6d2-e4df-43a0-899c-db688b4666b2', true, '{"selectedOptions":[0]}', 84, 'assessment', now() - interval '820707 seconds', 'because near the horizon sunlight passes through much more air; blue is scattered out along the way, leaving mainly the longer red wavelengths', 'sound'),
    ('f80c1bf7-623e-41c3-8358-3434208aaa3a', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '2879a720-6d0b-471c-8b09-15a59122afbe', true, '{"selectedOptions":[3]}', 109, 'assessment', now() - interval '820632 seconds', 'because for near objects the ciliary muscles contract, making the lens thicker and its focal length shorter; this is accommodation', 'sound'),
    ('debefe04-1c1a-40c5-84a9-3a92d612afb4', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'd222eaba-ac8f-401b-8d76-dd0437f502b8', true, '{"selectedOptions":[1]}', 87, 'assessment', now() - interval '820557 seconds', 'because the force is maximum when current and field are perpendicular, and zero when they are parallel', 'sound'),
    ('01ef1ad9-4b7c-4d84-8eaf-be6f8cbcdecc', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'b6dfdc1f-396a-47f7-8e21-fe986fc9157a', false, '{"selectedOptions":[0]}', 119, 'assessment', now() - interval '820482 seconds', 'Every ray changes direction when it enters glass.', 'flawed'),
    ('ad43df54-c9b1-4951-8486-5aaf1a4434c0', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'eb4f69d2-0789-422c-8ce4-f41abd669bba', true, '{"selectedOptions":[1]}', 85, 'practice', now() - interval '723937 seconds', 'because h = I²Rt, so doubling I multiplies the heat by 2² = 4', 'sound'),
    ('077bea92-53f2-4620-8c86-97ce7fd86be1', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'b10c49e6-b453-49d3-87a0-3f7385c2943a', true, '{"selectedOptions":[1]}', 56, 'practice', now() - interval '688537 seconds', 'Two 10 Ω resistors in parallel make 20 Ω.', 'flawed'),
    ('b2fbb363-62e2-49fd-8b39-6d2968c03fa1', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'cfe47243-9ba2-44b4-8749-5d5f805ea814', true, '{"selectedOptions":[1]}', 49, 'practice', now() - interval '665442 seconds', 'because kWh is power × time, so it measures energy; 1 kWh = 3.6 × 10⁶ J', 'sound'),
    ('120b5826-e55b-41eb-801d-9d80b0ad3173', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'c62151ab-4ce4-430b-83c5-96bb3a4055f1', true, '{"selectedOptions":[1]}', 21, 'practice', now() - interval '627798 seconds', 'because light travels in straight lines in a uniform medium, so the region behind an opaque object receives no light', 'sound'),
    ('45d3f7fc-0790-407c-81a4-7b72e55c5fa6', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'c0e4c20b-6ea5-46a7-84dd-0642a338f55b', true, '{"selectedOptions":[1]}', 98, 'practice', now() - interval '599795 seconds', 'Even a straight-in ray bends a little when it enters water.', 'flawed'),
    ('ba7cb49a-b503-4c29-8e4e-950cf46e8bb1', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', 'e8c0f160-32d0-4f92-809c-bf185454600f', true, '{"selectedOptions":[0]}', 80, 'practice', now() - interval '562462 seconds', 'because by convention, outside a magnet the field lines emerge from the north pole and enter the south pole', 'sound'),
    ('4449b0d9-bfd6-42b2-88f0-616af92a52fa', 'a61b8bfe-2647-470c-847a-4a4d5ff122d6', '5e83186b-b594-404d-82f8-3de6f40b50b0', true, '{"selectedOptions":[1]}', 37, 'practice', now() - interval '525793 seconds', 'because r = ρl/A: resistance falls with shorter length and with larger cross-sectional area', 'sound'),
