    ('f3a64704-5b2d-4aa5-883c-0a303cdde72b', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', '592dced7-4d6b-436b-8d7c-f2843b2a7f39', true, '{"selectedOptions":[2]}', 104, 'assessment', now() - interval '766803 seconds', 'because r = V²/P, so at the same voltage the lower-power 60 W bulb has the higher resistance', 'sound'),
    ('9e5225c9-41e5-49f3-874c-4ba27ab389c8', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', 'b10c49e6-b453-49d3-87a0-3f7385c2943a', true, '{"selectedOptions":[1]}', 58, 'assessment', now() - interval '766728 seconds', null, 'missing'),
    ('7191e538-b512-4905-8f72-c1f06f5dff1c', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', '2879a720-6d0b-471c-8b09-15a59122afbe', true, '{"selectedOptions":[3]}', 94, 'assessment', now() - interval '766653 seconds', 'because for near objects the ciliary muscles contract, making the lens thicker and its focal length shorter; this is accommodation', 'sound'),
    ('9bd24abc-a6e9-4b89-8ba0-83212483fc58', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', '0db96333-51ae-49ca-87c9-f1ff5a64b563', true, '{"selectedOptions":[1]}', 46, 'assessment', now() - interval '766578 seconds', 'because charge is not used up in a bulb; the same current flows all the way round a series loop', 'sound'),
    ('a154a353-a0ef-4692-87be-9a867c308290', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', 'b6dfdc1f-396a-47f7-8e21-fe986fc9157a', true, '{"selectedOptions":[2]}', 63, 'assessment', now() - interval '766503 seconds', 'because a ray along the normal does not change direction, but it still slows down because glass is optically denser than air', 'sound'),
    ('2aa155a4-b0cc-4f34-847d-728a1b39e1ef', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', 'd0085f80-340c-4135-870e-1601717cec6e', true, '{"selectedOptions":[2]}', 80, 'assessment', now() - interval '766428 seconds', null, 'missing'),
