    ('3ad79a03-94bf-474c-826d-0441afa4ed4f', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', '1f363bb6-9fdc-4436-83c4-ca9c632688f7', false, '{"selectedOptions":[2]}', 104, 'assessment', now() - interval '766278 seconds', null, 'missing'),
