    ('741746e5-6a90-4660-81fd-717f3e34170f', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', '88f87cea-896e-4b12-88f6-f92d31f32705', true, '{"selectedOptions":[1]}', 37, 'assessment', now() - interval '766128 seconds', 'because a concave (diverging) lens moves the image of distant objects back onto the retina', 'sound'),
