    ('089cca0b-b410-4f22-8285-accfd8efbea3', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', 'e8c0f160-32d0-4f92-809c-bf185454600f', true, '{"selectedOptions":[0]}', 103, 'practice', now() - interval '648038 seconds', 'because by convention, outside a magnet the field lines emerge from the north pole and enter the south pole', 'sound'),
