    ('33d9ae07-13be-46bc-8b81-63ea749a677f', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', '8c6a881e-5dac-43a6-8c89-95f6d21fa345', true, '{"selectedOptions":[1]}', 78, 'practice', now() - interval '521243 seconds', 'because white light is a mixture of colours; each colour has a slightly different refractive index in glass, so they separate (dispersion)', 'sound'),
    ('48c142a1-918d-4f0b-8d10-d97b1f60b4ca', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', '8c6a881e-5dac-43a6-8c89-95f6d21fa345', true, '{"selectedOptions":[1]}', 60, 'practice', now() - interval '482570 seconds', 'because white light is a mixture of colours; each colour has a slightly different refractive index in glass, so they separate (dispersion)', 'sound'),
