    ('c23997f0-efb6-4195-822d-e0eca220365c', 'fffc169d-bf34-4ef7-86fe-dd2d45560b68', 'c62151ab-4ce4-430b-83c5-96bb3a4055f1', true, '{"selectedOptions":[1]}', 79, 'practice', now() - interval '355873 seconds', null, 'missing'),
