    ('6ca68c0a-f6f1-48a5-8be9-a840ae23a02d', 'fd812a16-b45c-407e-88da-a30137e5d97b', 'b880fcf6-9d8f-4c5d-8cf3-03391dafa270', true, '{"selectedOptions":[0]}', 73, 'practice', now() - interval '643277 seconds', 'because a voltmeter compares two points, so it is connected in parallel across the component', 'sound'),
    ('bd4c1c36-6d14-46c7-8679-105d78f92051', 'fd812a16-b45c-407e-88da-a30137e5d97b', '9ead298c-2fd0-4e8f-8e03-c76afcce7178', true, '{"selectedOptions":[1]}', 38, 'practice', now() - interval '612383 seconds', 'because the eye lens is a convex lens that forms a real, inverted image on the retina; the brain interprets it as upright', 'sound'),
    ('3fcadabd-0b04-4566-89e5-63464666aab7', 'fd812a16-b45c-407e-88da-a30137e5d97b', '6d01d352-1fad-4078-8620-a0c767eababd', true, '{"selectedOptions":[0]}', 63, 'practice', now() - interval '579931 seconds', 'because myopia is near-sightedness: nearby objects are clear, but distant objects are blurred because their image forms in front of the retina', 'sound'),
