    ('6f6533a8-b4d4-4890-8db8-1d2412de1de7', 'fd812a16-b45c-407e-88da-a30137e5d97b', '3d7bc7a8-57f3-4937-817c-aa972998d375', true, '{"selectedOptions":[3]}', 25, 'practice', now() - interval '412674 seconds', null, 'missing'),
