    ('b99527df-94e0-4d30-86b4-1f49d88daa5d', 'fd812a16-b45c-407e-88da-a30137e5d97b', '0e26472d-1d73-4655-8d35-0755bcfe4c73', false, '{"selectedOptions":[1]}', 115, 'practice', now() - interval '258402 seconds', null, 'missing'),
