    ('cc9d1619-04eb-4279-8fed-8d593500dbb3', 'fd812a16-b45c-407e-88da-a30137e5d97b', 'dd5c1682-0093-477a-8bd8-ed8cafd851a7', false, '{"selectedOptions":[1]}', 94, 'practice', now() - interval '134779 seconds', null, 'missing'),
    ('ca665815-ace9-448b-8aa8-999a55e4a5ce', 'fd812a16-b45c-407e-88da-a30137e5d97b', '5e8571a5-2351-4fe0-8091-c30478579d1b', true, '{"selectedOptions":[3]}', 56, 'practice', now() - interval '111058 seconds', 'because the reflected ray makes 50° with the first mirror, so it meets the perpendicular mirror at 40° to its surface, giving an angle of incidence of 90° − 40° = 50°', 'sound'),
    ('4efedaa7-33b2-4454-8973-0f451a86a8e7', 'fd812a16-b45c-407e-88da-a30137e5d97b', '3c5eeb9a-a95e-42bb-8f0a-132371d6e2af', false, '{"selectedOptions":[0]}', 108, 'practice', now() - interval '55907 seconds', 'not sure', 'missing'),
