    ('57637238-26ae-423b-8a7f-95c5f15188dd', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', 'c0e4c20b-6ea5-46a7-84dd-0642a338f55b', true, '{"selectedOptions":[1]}', 39, 'assessment', now() - interval '755730 seconds', 'because light slows down in glass, an optically denser medium, so it bends towards the normal', 'sound'),
    ('f93503bb-37e4-4ca2-88dd-d1a42f60221a', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '592dced7-4d6b-436b-8d7c-f2843b2a7f39', true, '{"selectedOptions":[2]}', 39, 'assessment', now() - interval '755655 seconds', 'because r = V²/P, so at the same voltage the lower-power 60 W bulb has the higher resistance', 'sound'),
    ('44a10aba-8ab0-4c5d-819b-20603fb72b88', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '88f87cea-896e-4b12-88f6-f92d31f32705', false, '{"selectedOptions":[0]}', 33, 'assessment', now() - interval '755580 seconds', 'A convex lens will help a myopic person see distant objects.', 'flawed'),
    ('e8249102-a178-4fd1-8346-7860b33efbca', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '103c1ac5-09bf-46d4-8b75-3f1aca46fc84', true, '{"selectedOptions":[0]}', 40, 'assessment', now() - interval '755505 seconds', 'because for an object beyond 2F₁, a convex lens forms a real, inverted, diminished image between F₂ and 2F₂', 'sound'),
    ('cd76aca1-9463-463a-86e0-5209dd1268b2', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '0e26472d-1d73-4655-8d35-0755bcfe4c73', true, '{"selectedOptions":[2]}', 75, 'assessment', now() - interval '755430 seconds', 'because v = W/Q = 12 J / 3 C = 4 V', 'sound'),
    ('5eb3c8d2-90af-478c-84a9-daa3eb019be8', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', 'd222eaba-ac8f-401b-8d76-dd0437f502b8', true, '{"selectedOptions":[1]}', 70, 'assessment', now() - interval '755355 seconds', 'because the force is maximum when current and field are perpendicular, and zero when they are parallel', 'sound'),
    ('576c5f77-a8c4-44fa-8846-825683c1e693', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '0f25728e-daad-4fe2-8fe0-c906087dd055', true, '{"selectedOptions":[2]}', 79, 'assessment', now() - interval '755280 seconds', 'because with the object between P and F, a concave mirror forms a virtual, erect, magnified image behind the mirror, as in a shaving mirror', 'sound'),
    ('c4fb9357-76ee-484f-8f26-74368b415d23', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '1f363bb6-9fdc-4436-83c4-ca9c632688f7', false, '{"selectedOptions":[3]}', 44, 'assessment', now() - interval '755205 seconds', 'Current is split between the bulbs in series.', 'flawed'),
    ('5ca7085d-5046-4b11-84a7-386b07e40ed2', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', 'de06817c-4d9f-400d-8dec-1467419f33db', true, '{"selectedOptions":[0]}', 30, 'assessment', now() - interval '755130 seconds', 'because a fuse must melt quickly when excess current heats it, breaking the circuit, so it needs a low melting point', 'sound'),
    ('5deeabe5-8e9b-4031-8ab4-941d99ed3cce', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '5cafd5fc-1b47-4343-826b-fd378f3546e4', true, '{"selectedOptions":[1]}', 66, 'assessment', now() - interval '755055 seconds', 'because a planet is seen as a collection of point sources; their variations cancel out on average, so it does not twinkle', 'sound'),
