    ('ea323c2e-cc6f-468b-8a07-e7cfa44eb221', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '22dfed0c-ddec-460b-86f4-abb9c2a99a37', true, '{"selectedOptions":[0]}', 53, 'assessment', now() - interval '754905 seconds', 'because resistivity is a property of the material, so it does not change; each half has half the resistance, not half the resistivity', 'sound'),
    ('b7b3656a-745d-4262-88b0-ca62cebc98f3', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '7aa6c9b8-2cc6-40a5-879d-ea99f7618237', true, '{"selectedOptions":[1]}', 79, 'assessment', now() - interval '754830 seconds', 'because the tangent to a field line gives the field direction; a crossing would give two directions at one point', 'sound'),
    ('ce7b8617-8f1c-403c-87b3-97fff800206d', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '2879a720-6d0b-471c-8b09-15a59122afbe', true, '{"selectedOptions":[3]}', 101, 'assessment', now() - interval '754755 seconds', 'because for near objects the ciliary muscles contract, making the lens thicker and its focal length shorter; this is accommodation', 'sound'),
