    ('f7507bac-cf14-47b1-862f-6f0f940d787b', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '29bd2c12-f686-4c12-8517-dd85d63d704e', true, '{"selectedOptions":[2]}', 67, 'practice', now() - interval '350738 seconds', 'because i = Q/t = 60 C / 120 s = 0.5 A; time must be in seconds', 'sound'),
