    ('b77ee4bd-f7ad-4ffd-8854-e1c5bf9203c9', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '29bd2c12-f686-4c12-8517-dd85d63d704e', true, '{"selectedOptions":[2]}', 55, 'practice', now() - interval '248891 seconds', 'The ammeter after the bulb will read less.', 'flawed'),
    ('5a419059-e874-4abf-8ef4-8d1cb5f72761', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', 'c62151ab-4ce4-430b-83c5-96bb3a4055f1', true, '{"selectedOptions":[1]}', 89, 'practice', now() - interval '190442 seconds', 'because light travels in straight lines in a uniform medium, so the region behind an opaque object receives no light', 'sound'),
    ('bbb1de67-d800-450b-822b-9d1d430aa6e9', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '3c5eeb9a-a95e-42bb-8f0a-132371d6e2af', true, '{"selectedOptions":[2]}', 27, 'practice', now() - interval '139991 seconds', 'because angles are measured from the normal: the angle of incidence is 90° − 30° = 60°, so the angle of reflection is also 60°', 'sound'),
    ('fc5a527a-f64a-46bd-8375-3d24bbd81a66', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', 'f6eedc74-f4d2-42a3-82ff-f980229ee5bf', true, '{"selectedOptions":[1]}', 37, 'practice', now() - interval '108236 seconds', 'because the image is 2 m behind the mirror, so it is 2 m + 2 m = 4 m from you', 'sound'),
    ('93fc12e5-a281-4921-87f7-dfde4de4b00f', 'fed9cd62-cac8-4110-8df5-9aa5407ea607', '8b85080d-82ba-4b9d-8fcc-95aabf40a3a4', false, '{"selectedOptions":[2]}', 21, 'practice', now() - interval '51516 seconds', null, 'missing'),
