    ('fe3ba090-fcad-411a-8038-7f9f79b38b66', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', '592dced7-4d6b-436b-8d7c-f2843b2a7f39', false, '{"selectedOptions":[0]}', 27, 'assessment', now() - interval '762661 seconds', 'A 100 W bulb is brighter because it has more resistance.', 'flawed'),
    ('04796d4f-37f6-4efa-8a1e-0b3ede9ebb5b', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', '88f87cea-896e-4b12-88f6-f92d31f32705', false, '{"selectedOptions":[0]}', 32, 'assessment', now() - interval '762586 seconds', 'Short-sighted people need a magnifying lens to see far.', 'flawed'),
    ('ee9c52af-fe7d-4f93-8109-e526bf6e4707', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', '14cc0e3b-8f51-40ee-89d9-3d49053223ab', true, '{"selectedOptions":[2]}', 110, 'assessment', now() - interval '762511 seconds', 'because violet has the highest refractive index in glass, so it bends the most; red bends the least', 'sound'),
    ('f5162889-4474-490c-8ec6-dfbea096ecff', '7e98a5c9-93e9-4c06-8338-755f0bf235b1', 'b10c49e6-b453-49d3-87a0-3f7385c2943a', true, '{"selectedOptions":[1]}', 74, 'assessment', now() - interval '762436 seconds', 'because each branch gets the full 4 V, so I = V/R = 4/2 = 2 A through the 2 Ω resistor (and 0.5 A through the 8 Ω)', 'sound'),
