    ('5b635a04-a5b4-4f0a-8fa7-2b435becf930', '84b0f493-42ce-4d9d-8d2c-d82f5cf29837', '29bd2c12-f686-4c12-8517-dd85d63d704e', true, '{"selectedOptions":[2]}', 29, 'practice', now() - interval '204863 seconds', 'because i = Q/t = 60 C / 120 s = 0.5 A; time must be in seconds', 'sound'),
