    ('3e0ea497-20e7-4b09-8018-6f3433f59745', '84b0f493-42ce-4d9d-8d2c-d82f5cf29837', '5e83186b-b594-404d-82f8-3de6f40b50b0', true, '{"selectedOptions":[1]}', 43, 'practice', now() - interval '84839 seconds', null, 'missing'),
