    ('081ba01f-8e7c-49bd-80aa-5227ba658c71', '7d4b9ad8-6085-4a1f-8b0b-94b47ceced3e', '592dced7-4d6b-436b-8d7c-f2843b2a7f39', false, '{"selectedOptions":[0]}', 27, 'assessment', now() - interval '845594 seconds', 'not sure', 'missing'),
