    ('702def99-6b15-4a37-81f5-aadf55a1c373', '6441f697-a993-4c64-83a5-e548e10baf79', 'e8c0f160-32d0-4f92-809c-bf185454600f', false, '{"selectedOptions":[3]}', 30, 'practice', now() - interval '652386 seconds', null, 'missing'),
