    ('d9ffdd16-cc4c-47e5-8207-d53b70126c8f', '6441f697-a993-4c64-83a5-e548e10baf79', '29bd2c12-f686-4c12-8517-dd85d63d704e', false, '{"selectedOptions":[1]}', 50, 'practice', now() - interval '579982 seconds', null, 'missing'),
