    ('3dc76d4a-c7c9-46c0-8c30-2b76a9f325e9', '6441f697-a993-4c64-83a5-e548e10baf79', 'b880fcf6-9d8f-4c5d-8cf3-03391dafa270', true, '{"selectedOptions":[0]}', 26, 'practice', now() - interval '535837 seconds', 'because a voltmeter compares two points, so it is connected in parallel across the component', 'sound'),
