    ('b6be2da9-71df-49f3-8213-4e51fc66d6d1', '6441f697-a993-4c64-83a5-e548e10baf79', 'c62151ab-4ce4-430b-83c5-96bb3a4055f1', true, '{"selectedOptions":[1]}', 31, 'practice', now() - interval '511789 seconds', null, 'missing'),
    ('21ad28ba-09fc-4a57-8824-e3aa14ed2eb4', '6441f697-a993-4c64-83a5-e548e10baf79', 'b10c49e6-b453-49d3-87a0-3f7385c2943a', true, '{"selectedOptions":[1]}', 59, 'practice', now() - interval '498716 seconds', 'because each branch gets the full 4 V, so I = V/R = 4/2 = 2 A through the 2 Ω resistor (and 0.5 A through the 8 Ω)', 'sound'),
    ('72328039-aacc-4689-8bb4-4a55ed43d457', '6441f697-a993-4c64-83a5-e548e10baf79', '0e26472d-1d73-4655-8d35-0755bcfe4c73', true, '{"selectedOptions":[2]}', 44, 'practice', now() - interval '486890 seconds', 'because v = W/Q = 12 J / 3 C = 4 V', 'sound'),
    ('9ab3ff32-9382-42bb-804e-b6c9556b6671', '6441f697-a993-4c64-83a5-e548e10baf79', 'edf67eb8-a7eb-431b-8693-5037ea7581ce', true, '{"selectedOptions":[2]}', 62, 'practice', now() - interval '480802 seconds', null, 'missing'),
    ('c690bf3c-44a0-4796-83ae-be259ff959a6', '6441f697-a993-4c64-83a5-e548e10baf79', '3c5eeb9a-a95e-42bb-8f0a-132371d6e2af', true, '{"selectedOptions":[2]}', 107, 'practice', now() - interval '467420 seconds', 'because angles are measured from the normal: the angle of incidence is 90° − 30° = 60°, so the angle of reflection is also 60°', 'sound'),
    ('27d13f38-b006-4b9c-826d-db8132819a43', '6441f697-a993-4c64-83a5-e548e10baf79', 'eb4f69d2-0789-422c-8ce4-f41abd669bba', true, '{"selectedOptions":[1]}', 34, 'practice', now() - interval '455223 seconds', 'because h = I²Rt, so doubling I multiplies the heat by 2² = 4', 'sound'),
    ('157ba612-2e0b-457a-8427-065791a097db', '6441f697-a993-4c64-83a5-e548e10baf79', 'de054d88-7c0a-4f0b-88dd-1526ae8bf1b4', true, '{"selectedOptions":[2]}', 79, 'practice', now() - interval '443579 seconds', 'because for a spherical mirror f = R/2, so f = 30/2 = 15 cm', 'sound'),
    ('55eeac83-f4ed-49b1-88a4-6e82a97694b4', '6441f697-a993-4c64-83a5-e548e10baf79', '03cf46c1-c050-4597-829e-9732e621b333', false, '{"selectedOptions":[0]}', 102, 'practice', now() - interval '429195 seconds', 'Drivers need a magnifying mirror, so it must be concave.', 'flawed'),
    ('4729adbf-ad4a-4f31-877f-bf473e1e1ba3', '6441f697-a993-4c64-83a5-e548e10baf79', '0f25728e-daad-4fe2-8fe0-c906087dd055', true, '{"selectedOptions":[2]}', 59, 'practice', now() - interval '417829 seconds', 'because with the object between P and F, a concave mirror forms a virtual, erect, magnified image behind the mirror, as in a shaving mirror', 'sound'),
    ('2580c3c8-5fc2-419c-8502-fc9a95e341a0', '6441f697-a993-4c64-83a5-e548e10baf79', '5e83186b-b594-404d-82f8-3de6f40b50b0', true, '{"selectedOptions":[1]}', 101, 'practice', now() - interval '408702 seconds', 'because r = ρl/A: resistance falls with shorter length and with larger cross-sectional area', 'sound'),
    ('98612a83-1c57-4f84-8fbd-7e0c2a5a71e5', '6441f697-a993-4c64-83a5-e548e10baf79', 'e8c0f160-32d0-4f92-809c-bf185454600f', true, '{"selectedOptions":[0]}', 92, 'practice', now() - interval '398234 seconds', 'because by convention, outside a magnet the field lines emerge from the north pole and enter the south pole', 'sound'),
    ('3c2ee3b6-cd5e-419f-8ae2-89c5a04c9ae7', '6441f697-a993-4c64-83a5-e548e10baf79', '8b85080d-82ba-4b9d-8fcc-95aabf40a3a4', true, '{"selectedOptions":[0]}', 99, 'practice', now() - interval '384699 seconds', null, 'missing'),
    ('8b332dca-959d-4c74-8bf1-f32415425f5c', '6441f697-a993-4c64-83a5-e548e10baf79', '4ef8a9a1-5e87-442c-8e37-bd9b7f730cc5', true, '{"selectedOptions":[0]}', 44, 'practice', now() - interval '370905 seconds', 'because the fuse goes in the live wire so that when it melts, the appliance is disconnected from the high-potential supply', 'sound'),
    ('1d0e7a25-5f61-46fd-845e-144293ebf2be', '6441f697-a993-4c64-83a5-e548e10baf79', '80d72bba-3c7b-4ad9-89b1-043f0d2aafd8', true, '{"selectedOptions":[1]}', 39, 'practice', now() - interval '360762 seconds', 'because a straight current produces circular field lines centred on the wire, in planes perpendicular to it', 'sound'),
    ('7cc5fb3d-59ef-4773-842c-01464f32fda5', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', 'b28ac269-650b-4292-8975-4380c3952d5a', false, '{"selectedOptions":[0]}', 21, 'assessment', now() - interval '855005 seconds', 'More resistors always means more resistance.', 'flawed'),
    ('9d4e64fa-a176-4828-8c4f-c26a81dee8c5', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', '592dced7-4d6b-436b-8d7c-f2843b2a7f39', false, '{"selectedOptions":[0]}', 58, 'assessment', now() - interval '854930 seconds', 'A 100 W bulb is brighter because it has more resistance.', 'flawed'),
    ('636b899c-e72e-426d-8226-1c168d8761f3', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', '103c1ac5-09bf-46d4-8b75-3f1aca46fc84', true, '{"selectedOptions":[0]}', 54, 'assessment', now() - interval '854855 seconds', null, 'missing'),
    ('21700414-ea42-438a-8e35-8c01ae89e66b', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', '1f363bb6-9fdc-4436-83c4-ca9c632688f7', true, '{"selectedOptions":[1]}', 63, 'assessment', now() - interval '854780 seconds', 'because in series the same current flows through every component, so identical bulbs glow equally', 'sound'),
    ('ce52a303-1559-423f-8997-f4a6eeae50da', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', 'e050b0d8-cb71-41cf-8059-c1c1a8feefce', true, '{"selectedOptions":[1]}', 65, 'assessment', now() - interval '854705 seconds', 'because a convex mirror diverges light; parallel rays reflect so that they appear to come from the principal focus behind the mirror', 'sound'),
    ('b9a41f2b-56c2-4d07-80ea-e1bf33f3b007', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', '43770002-8762-4881-8ec9-d41ad7e134dd', true, '{"selectedOptions":[2]}', 39, 'assessment', now() - interval '854630 seconds', 'because optical density depends on refractive index, not mass density; kerosene has the higher n, so light is slower in it', 'sound'),
