    ('7d74a9bf-b192-41f4-87d6-0ed799f8b089', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', 'fac59f2d-cfcd-43b8-8063-553e8b9373ca', true, '{"selectedOptions":[2]}', 112, 'assessment', now() - interval '854480 seconds', 'because f = 1/P = 1/(−2.5) m = −0.4 m = −40 cm; a negative focal length means a concave lens', 'sound'),
    ('036a36e2-52e6-45be-8eb8-35c132e43996', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', '5cafd5fc-1b47-4343-826b-fd378f3546e4', true, '{"selectedOptions":[1]}', 62, 'assessment', now() - interval '854405 seconds', 'because a planet is seen as a collection of point sources; their variations cancel out on average, so it does not twinkle', 'sound'),
    ('e8da0177-da33-418e-8322-829c517f90ac', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', '2879a720-6d0b-471c-8b09-15a59122afbe', true, '{"selectedOptions":[3]}', 46, 'assessment', now() - interval '854330 seconds', null, 'missing'),
    ('50fb3497-3f04-4527-8ee2-f9895e467dbd', 'a5cba874-c95d-4ff2-8fa4-0911a427f3ea', '14cc0e3b-8f51-40ee-89d9-3d49053223ab', true, '{"selectedOptions":[2]}', 33, 'assessment', now() - interval '854255 seconds', 'because violet has the highest refractive index in glass, so it bends the most; red bends the least', 'sound'),
