    ('d7d8d816-c16b-4e8e-8414-57c429e5d4b6', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '03b0bda2-ed58-4241-8edf-8d12b3bf13a1', false, '{"selectedOptions":[1]}', 84, 'assessment', now() - interval '699057 seconds', 'Fleming''s right-hand rule gives the force on the wire.', 'flawed'),
    ('a8e3bff0-e5a3-4252-80a1-1a684f4bb270', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '86a8521f-3073-45e5-89bf-0d0d84d2f58a', true, '{"selectedOptions":[2]}', 83, 'assessment', now() - interval '698982 seconds', 'because a plane mirror always forms an image the same size as the object; it only looks smaller from farther away because it is more distant', 'sound'),
    ('e0dc8fbc-77fb-4fdb-8d11-5c842fbef37d', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '7a38d880-3b17-4284-89e5-9520930e929b', true, '{"selectedOptions":[0]}', 91, 'assessment', now() - interval '698907 seconds', 'Kerosene is lighter than water, so light bends less in it.', 'flawed'),
    ('f38ec21a-6ded-420d-8272-7bf79d7a0408', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '103c1ac5-09bf-46d4-8b75-3f1aca46fc84', true, '{"selectedOptions":[0]}', 64, 'assessment', now() - interval '698832 seconds', 'because for an object beyond 2F₁, a convex lens forms a real, inverted, diminished image between F₂ and 2F₂', 'sound'),
    ('90049ad6-208a-46f5-88d8-ef643079b0ea', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'dd5c1682-0093-477a-8bd8-ed8cafd851a7', false, '{"selectedOptions":[2]}', 74, 'assessment', now() - interval '698757 seconds', null, 'missing'),
