    ('a61d6bd8-18ac-4850-8a58-3a0dcfae1e46', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '22dfed0c-ddec-460b-86f4-abb9c2a99a37', false, '{"selectedOptions":[1]}', 67, 'assessment', now() - interval '698532 seconds', 'not sure', 'missing'),
    ('7dc76f8d-2b15-4c40-8041-d20a89fb8392', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '592dced7-4d6b-436b-8d7c-f2843b2a7f39', true, '{"selectedOptions":[2]}', 107, 'assessment', now() - interval '698457 seconds', 'because r = V²/P, so at the same voltage the lower-power 60 W bulb has the higher resistance', 'sound'),
    ('abd32f76-d7fd-437f-8cba-1d80112eb62d', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '6ca49128-eaea-41b4-8324-b19fdbcaca07', false, '{"selectedOptions":[0]}', 61, 'assessment', now() - interval '698382 seconds', null, 'missing'),
    ('d030fd7a-8b21-4684-879e-ac103aa458fb', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '3d7bc7a8-57f3-4937-817c-aa972998d375', true, '{"selectedOptions":[3]}', 78, 'assessment', now() - interval '698307 seconds', 'because we see an object when light from a source is reflected by the object into our eyes; eyes receive light, they do not send it out', 'sound'),
    ('c49d2ebc-c4b2-46a0-842f-2b759c1c1d28', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'b6dfdc1f-396a-47f7-8e21-fe986fc9157a', true, '{"selectedOptions":[2]}', 87, 'practice', now() - interval '608005 seconds', 'because a ray along the normal does not change direction, but it still slows down because glass is optically denser than air', 'sound'),
    ('3aca2ab4-6d71-4562-819a-35f1d7294e77', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '29bd2c12-f686-4c12-8517-dd85d63d704e', true, '{"selectedOptions":[2]}', 97, 'practice', now() - interval '599589 seconds', 'because i = Q/t = 60 C / 120 s = 0.5 A; time must be in seconds', 'sound'),
    ('bd497410-ae00-40e3-85ea-af40094e3d7a', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '3643ebfb-16be-4667-859b-35f4648b1ec3', true, '{"selectedOptions":[0]}', 69, 'practice', now() - interval '591903 seconds', 'because changing air layers keep shifting the path of starlight, so the amount of light entering the eye flickers', 'sound'),
    ('385be8f1-1158-4259-8626-0d6fb4b8ec63', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '3c5eeb9a-a95e-42bb-8f0a-132371d6e2af', true, '{"selectedOptions":[2]}', 60, 'practice', now() - interval '579346 seconds', 'because angles are measured from the normal: the angle of incidence is 90° − 30° = 60°, so the angle of reflection is also 60°', 'sound'),
    ('109d3564-c9dd-4655-89c3-ca3c1f1ea180', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '8c6a881e-5dac-43a6-8c89-95f6d21fa345', true, '{"selectedOptions":[1]}', 60, 'practice', now() - interval '568618 seconds', 'because white light is a mixture of colours; each colour has a slightly different refractive index in glass, so they separate (dispersion)', 'sound'),
    ('0e0a2da2-5fde-4835-8964-db8065fce270', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', '26e8621b-f9c4-456a-86b1-19072abc896c', true, '{"selectedOptions":[1]}', 68, 'practice', now() - interval '560886 seconds', 'because air molecules are much smaller than the wavelength of visible light and scatter shorter (blue) wavelengths much more strongly', 'sound'),
    ('eb64611b-5a7f-4008-8e3c-b3f3b149a6d0', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'b880fcf6-9d8f-4c5d-8cf3-03391dafa270', true, '{"selectedOptions":[0]}', 76, 'practice', now() - interval '550966 seconds', 'because a voltmeter compares two points, so it is connected in parallel across the component', 'sound'),
    ('4a38acfb-b6b3-4bbf-87ea-35bcd6fb9dbf', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'de054d88-7c0a-4f0b-88dd-1526ae8bf1b4', true, '{"selectedOptions":[2]}', 85, 'practice', now() - interval '541713 seconds', 'because for a spherical mirror f = R/2, so f = 30/2 = 15 cm', 'sound'),
    ('845169e2-bf4a-4f38-81df-8832260eada5', 'a3336cb3-5075-4550-8b12-ee7ccf996ff5', 'edf67eb8-a7eb-431b-8693-5037ea7581ce', true, '{"selectedOptions":[2]}', 108, 'practice', now() - interval '531952 seconds', 'because free electrons move randomly, but a net flow of charge needs a potential difference across the conductor', 'sound'),
